eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   powerpointModule2Lessons: () => (/* binding */ powerpointModule2Lessons)\n/* harmony export */ });\nconst powerpointModule2Lessons = [\n    {\n        slug: \"powerpoint-text-basics\",\n        title: \"PowerPoint Text Basics\",\n        description: \"Learn how to select text, cut, copy, paste, drag text, and format text using the tools on the Home tab.\",\n        duration: \"9 min\",\n        videoUrl: \"https://www.youtube.com/embed/F9RL0Lk5cmw\",\n        practiceFiles: [\n            {\n                name: \"PowerPoint Text Basics Practice File\",\n                url: \"/practice/powerpoint/module-2/text-basics/Powerpoint_TextBasics_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Selecting Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Before you can edit or move text in PowerPoint, you first need to select it. Selecting text allows you to copy it, delete it, format it, or move it to another location on the slide.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To select text, click next to the text you want to select, then click and drag your mouse across the words.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_select_text.png\",\n                        alt: \"Selecting text in a PowerPoint text box\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Once the text is highlighted, PowerPoint knows that any commands you choose will apply to that selection.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Copying and Pasting Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Copying text allows you to duplicate information without removing the original content from the slide.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"First select the text you want to copy. Then click the Copy command in the Clipboard group on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_copy.png\",\n                        alt: \"Copy command on the PowerPoint ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Next place the insertion point where you want the copied text to appear and click the Paste command.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_paste_command.png\",\n                        alt: \"Paste command on the PowerPoint ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The copied text will appear in the new location while the original text remains unchanged.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Cutting and Pasting Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want to move text instead of copying it, you can use the Cut command. Cutting removes the selected text and places it on the clipboard.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Select the text you want to move, then click the Cut command on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_cut.png\",\n                        alt: \"Cut command on the PowerPoint ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Place the insertion point where the text should appear, then click Paste.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_paste.png\",\n                        alt: \"Pasting text into a new position\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The text will appear in its new location and will be removed from its original position.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Dragging and Dropping Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Another quick way to move text is by dragging and dropping it. This allows you to move text directly without using the Ribbon commands.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"First select the text you want to move. Then click and drag the selected text to a new location within the text box.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_drag_select_text.png\",\n                        alt: \"Dragging selected text in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"When you release the mouse, the text will move to the new location.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_dragged_text.png\",\n                        alt: \"Text moved to a new location on the slide\"\n                    }\n                ]\n            },\n            {\n                heading: \"Formatting Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Formatting text helps emphasize important information and makes slides easier to read.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The Home tab contains several tools for formatting text, including options for font style, font size, color, and alignment.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_ribbon_commands.png\",\n                        alt: \"Font and paragraph commands in the PowerPoint ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also apply styles such as bold, italic, or underline to highlight important information for your audience.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Slide Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After editing and formatting the text, the slide will appear more organized and easier to read.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The example below shows how the slide should look after rearranging the list and formatting the text.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg\",\n                        alt: \"Completed PowerPoint slide example\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Select slide 4.\",\n                    \"Move the text 'Lower blood pressure' so it appears between 'Companionship' and 'Social opportunities'.\",\n                    \"Use either Cut and Paste or Drag and Drop.\",\n                    \"Select the list of benefits and apply italics formatting.\",\n                    \"Select the title 'Did You Know?' remove the bold formatting and change the font size to 36 pt.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg\",\n                alt: \"Final result for the text basics challenge\"\n            }\n        ]\n    },\n    {\n        slug: \"powerpoint-lists\",\n        title: \"PowerPoint Lists\",\n        description: \"Learn how to create bulleted and numbered lists to organize information clearly on slides.\",\n        duration: \"8 min\",\n        videoUrl: \"https://www.youtube.com/embed/hL5XQGFdmDo\",\n        practiceFiles: [\n            {\n                name: \"Lists Practice File\",\n                url: \"/practice/powerpoint/module-2/lists/Powerpoint_Lists_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Bulleted Lists\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Bulleted lists are commonly used in PowerPoint to organize information into clear and easy-to-read points.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To add bullets, select the text you want to format and click the Bullets command in the Paragraph group on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_command.png\",\n                        alt: \"Bullets command in the PowerPoint ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also click the drop-down arrow next to the Bullets command to choose from different bullet styles.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_dropdown.png\",\n                        alt: \"Bullet style dropdown menu\"\n                    }\n                ]\n            },\n            {\n                heading: \"Choosing a Bullet Style\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint includes several built-in bullet styles such as circles, squares, arrows, and checkmarks.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Selecting a style immediately updates the appearance of the list.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_style.png\",\n                        alt: \"Selecting a bullet style in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Customizing Bullets\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want more control over the appearance of your bullets, you can open the Bullets and Numbering dialog box.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"From here you can change the bullet style, adjust the size, or select a different color.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_and_numbering.png\",\n                        alt: \"Bullets and Numbering dialog box\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also click Customize to choose symbols or other bullet characters.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_symbol_dialog.png\",\n                        alt: \"Symbol dialog used for custom bullets\"\n                    }\n                ]\n            },\n            {\n                heading: \"Numbered Lists\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Numbered lists are useful when presenting steps, instructions, or information that should appear in a specific order.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To apply numbering, select the text and click the Numbering command on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_numbering_command.png\",\n                        alt: \"Numbering command in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click the drop-down arrow next to the Numbering button to choose from different numbering formats.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_number_options.png\",\n                        alt: \"Numbered list formatting options\"\n                    }\n                ]\n            },\n            {\n                heading: \"Continuing Numbering\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"When you create numbered lists across multiple slides or sections, PowerPoint can continue numbering automatically.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can adjust where numbering starts by opening the Bullets and Numbering dialog box and changing the Start At value.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering.png\",\n                        alt: \"Changing numbering start value\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering_displayed.png\",\n                        alt: \"Numbering continued across a list\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Slide Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After applying bullets or numbering and customizing the formatting, your slide will look more organized and easier for your audience to read.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png\",\n                        alt: \"Final result of formatted lists on a PowerPoint slide\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Select the slide that contains the agenda list.\",\n                    \"Convert the list into a numbered list.\",\n                    \"Change the numbering so the list starts at 5.\",\n                    \"Customize the bullet style for another list on the slide.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png\",\n                alt: \"Final result for the lists challenge\"\n            }\n        ]\n    },\n    {\n        slug: \"indents-and-line-spacing\",\n        title: \"Indents and Line Spacing\",\n        description: \"Learn how to adjust paragraph indentation and spacing to improve slide readability.\",\n        duration: \"11 min\",\n        videoUrl: \"https://www.youtube.com/embed/fhLlISfmGqA\",\n        practiceFiles: [\n            {\n                name: \"Indents and Line Spacing Practice File\",\n                url: \"/practice/powerpoint/module-2/indents/Powerpoint_IndentsLineSpacing_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Why Indents and Spacing Matter\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Indentation and line spacing help organize text so information is easier for your audience to read.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Indentation creates hierarchy within lists and paragraphs, while line spacing controls the vertical distance between lines of text.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Showing the Ruler\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The ruler provides visual controls that allow you to adjust indentation precisely.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"If the ruler is not visible, go to the View tab and check the Ruler option.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_show_ruler.png\",\n                        alt: \"Turning on the ruler in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Understanding Indent Markers\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The ruler contains several markers that control how text is indented.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_first_line_marker.png\",\n                        alt: \"First line indent marker\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The first-line indent marker controls where the first line of a paragraph begins.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker.png\",\n                        alt: \"Hanging indent marker\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The hanging indent marker controls the indentation of every line except the first.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker.png\",\n                        alt: \"Left indent marker\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The left indent marker moves the entire paragraph inward.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Adjusting Indentation\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can adjust bullet alignment by dragging the indent markers on the ruler.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This allows you to control how far bullet points and text appear from the left side of the slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example.png\",\n                        alt: \"Example of adjusting the left indent marker\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example_dragged.png\",\n                        alt: \"Left indent marker dragged\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Hanging Indents\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The hanging indent marker controls how lines wrap after the first line of text.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example.png\",\n                        alt: \"Hanging indent marker example\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example_dragged.png\",\n                        alt: \"Dragging the hanging indent marker\"\n                    }\n                ]\n            },\n            {\n                heading: \"Creating Multilevel Lists\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Indentation can also be used to create multilevel lists that organize information into main topics and subtopics.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_list_multilevel.png\",\n                        alt: \"Multilevel bullet list example\"\n                    }\n                ]\n            },\n            {\n                heading: \"Adjusting Line Spacing\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Line spacing controls how much vertical space appears between lines of text.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To change line spacing, select the text and click the Line Spacing button in the Paragraph group on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_size.png\",\n                        alt: \"Line spacing menu\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can select common spacing options such as 1.0, 1.5, or 2.0.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_example.png\",\n                        alt: \"Line spacing example\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Line Spacing Options\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"For more precise control, open Line Spacing Options from the dropdown menu.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_options.png\",\n                        alt: \"Line spacing options dialog box\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can adjust spacing before and after paragraphs to improve readability.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_adjusted.png\",\n                        alt: \"Adjusted line spacing\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Slide Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After adjusting indentation and line spacing, the slide will appear more organized and easier to read.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/indents/indents-spacing_final_result.png\",\n                        alt: \"Completed PowerPoint slide\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Navigate to the slide containing the agenda.\",\n                    \"Select the bulleted list.\",\n                    \"Change the line spacing using Line Spacing Options.\",\n                    \"Show the ruler if it is not already visible.\",\n                    \"Adjust the left indent marker to align the bullet points.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-2/indents/indents-spacing_final_result.png\",\n                alt: \"Final result of the indents and spacing challenge\"\n            }\n        ]\n    },\n    {\n        slug: \"using-find-and-replace\",\n        title: \"Using Find & Replace in PowerPoint\",\n        description: \"Learn how to quickly locate text in your presentation and replace it with new content using the Find and Replace tools.\",\n        duration: \"7 min\",\n        videoUrl: \"https://www.youtube.com/embed/TEqzwdC4x58\",\n        practiceFiles: [\n            {\n                name: \"Find and Replace Practice File\",\n                url: \"/practice/powerpoint/module-2/find-replace/Powerpoint_FindReplace_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Finding Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Find tool allows you to search for specific words or phrases within your presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This is useful when working with presentations that contain many slides or repeated information.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To use Find, go to the Home tab and click the Find command in the Editing group.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_find_command.png\",\n                        alt: \"Find command in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The Find dialog box will appear where you can enter the word or phrase you want to locate.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_find_next.png\",\n                        alt: \"Find dialog box in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Locating Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After entering the search text, click Find Next to move through the presentation and locate each occurrence.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"When PowerPoint finds the text, it will highlight the matching word or phrase on the slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_text_found.jpeg\",\n                        alt: \"Highlighted search result in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Replace\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Replace feature allows you to search for text and replace it with different text automatically.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This tool is especially useful when you need to update names, dates, or repeated information across multiple slides.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To open Replace, click the Replace command in the Editing group on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_replace_command.png\",\n                        alt: \"Replace command in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The Replace dialog box allows you to enter both the text you want to find and the text you want to replace it with.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_replace_dialog.png\",\n                        alt: \"Replace dialog box\"\n                    }\n                ]\n            },\n            {\n                heading: \"Replacing Text\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Once the text is found, you can click Replace to change the highlighted occurrence.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_replace_execute.png\",\n                        alt: \"Replacing text in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want PowerPoint to replace every occurrence of the text in the presentation, click Replace All.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_replace_finished.jpeg\",\n                        alt: \"PowerPoint confirmation after replacing text\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Slide Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After replacing the text, the updated content will appear throughout the presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This allows you to quickly update repeated information without manually editing each slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-2/find-replace/find-replace_final_result.png\",\n                        alt: \"Completed slide after replacing text\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the presentation.\",\n                    \"Use the Find command to search for the text '2015-2016'.\",\n                    \"Use Replace to change it to '2016-2017'.\",\n                    \"Click Replace All to update every occurrence.\",\n                    \"Confirm the changes when PowerPoint displays the replacement message.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-2/find-replace/find-replace_final_result.png\",\n                alt: \"Final result of the Find and Replace challenge\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/content/ms-office/powerpoint/module2Lessons.ts\n");

