eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   powerpointModule3Lessons: () => (/* binding */ powerpointModule3Lessons)\n/* harmony export */ });\nconst powerpointModule3Lessons = [\n    {\n        slug: \"applying-themes\",\n        title: \"Applying Themes\",\n        description: \"Learn how to quickly change the design of your presentation using built-in PowerPoint themes.\",\n        duration: \"8 min\",\n        videoUrl: \"https://www.youtube.com/embed/_gYShFl6i94\",\n        practiceFiles: [\n            {\n                name: \"Applying Themes Practice File\",\n                url: \"/practice/powerpoint/module-3/themes/Powerpoint_Themes_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"What is a Theme?\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"A theme is a predefined combination of colors, fonts, layouts, and visual effects that control the overall appearance of a presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint presentations use a theme by default. Even if you never choose one manually, the Office theme is already applied when you create a new presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Applying a theme allows you to instantly change the design of every slide while keeping the presentation consistent and professional.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_example.png\",\n                        alt: \"Two slides showing different PowerPoint themes applied\"\n                    }\n                ]\n            },\n            {\n                heading: \"Theme Elements\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Every PowerPoint theme includes a set of design elements that work together to control the appearance of your slides.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"These elements ensure that colors, fonts, and design effects remain consistent throughout the entire presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The three main theme elements are theme colors, theme fonts, and theme effects.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_theme_colors.png\",\n                        alt: \"Theme colors menu in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme colors define the color palette used throughout the presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_theme_fonts.png\",\n                        alt: \"Theme fonts shown in PowerPoint font menu\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme fonts determine the default fonts used for headings and body text.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_theme_effects.png\",\n                        alt: \"Theme effects and shape styles in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme effects control the appearance of shapes, SmartArt graphics, and other design elements.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Applying a Theme\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"All themes in PowerPoint are located on the Design tab in the Themes group.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can apply a theme at any time, and PowerPoint will automatically update every slide in the presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To apply a theme, open the Design tab and locate the Themes group.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_more_themes.png\",\n                        alt: \"Themes group on the PowerPoint Design tab\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click the More arrow to view the complete gallery of available themes.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_desired_themes.png\",\n                        alt: \"PowerPoint theme gallery\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Select the theme you want and it will immediately be applied to the entire presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_applied_theme.png\",\n                        alt: \"Theme applied to PowerPoint presentation\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Theme Variants\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After applying a theme, you can change the appearance of that theme by choosing a variant.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Variants adjust the color scheme while keeping the same overall theme layout and design.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_variant_theme.png\",\n                        alt: \"Theme variants options in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This allows you to quickly explore different design options without changing the entire theme.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Presentation Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After applying a theme and selecting a variant, your slides will have a consistent design and professional appearance.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg\",\n                        alt: \"Final presentation with applied theme\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Select the Design tab.\",\n                    \"Open the Themes gallery.\",\n                    \"Apply the Gallery theme.\",\n                    \"Select a different theme variant.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg\",\n                alt: \"Final result after applying a theme\"\n            }\n        ]\n    },\n    {\n        slug: \"modifying-themes\",\n        title: \"Modifying Themes\",\n        description: \"Learn how to customize PowerPoint themes by changing theme colors, fonts, effects, and background styles.\",\n        duration: \"10 min\",\n        videoUrl: \"https://www.youtube.com/embed/UH7Gzjd3rGA\",\n        practiceFiles: [\n            {\n                name: \"Modifying Themes Practice File\",\n                url: \"/practice/powerpoint/module-3/modifying/Powerpoint_ModifyingThemes_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Modifying PowerPoint Themes\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint themes control the overall appearance of your presentation, including colors, fonts, and visual effects.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"If you like the general design of a theme but want to adjust certain elements, you can modify the theme instead of choosing a completely different one.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can change theme colors, fonts, effects, and background styles while keeping the overall layout of the theme.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_variant_dropdown.png\",\n                        alt: \"Variants dropdown menu in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing Theme Colors\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you don't like the colors of a theme, you can quickly apply a different color set while keeping the rest of the theme unchanged.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme colors control the color palette used for text, shapes, charts, and other design elements in your presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_variant_colors.png\",\n                        alt: \"Theme color options in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To change theme colors, open the Design tab, click the Variants drop-down arrow, select Colors, and choose the desired color set.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Customizing Theme Colors\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If none of the built-in color sets match your design needs, you can create your own custom theme colors.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Custom colors allow you to control the exact colors used for text backgrounds, accents, and hyperlinks.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_customize_colors.png\",\n                        alt: \"Customize theme colors dialog box\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Open Design → Variants → Colors → Customize Colors, then choose new colors and give your custom theme a name before saving it.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing Theme Fonts\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme fonts define the default fonts used for headings and body text across the entire presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Changing theme fonts helps keep text consistent throughout all slides.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_variant_font.png\",\n                        alt: \"Theme fonts menu in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To change fonts, open the Design tab, click Variants, select Fonts, and choose a font pair from the list.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Customizing Theme Fonts\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want to use specific fonts, you can create your own custom theme font combination.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This allows you to choose one font for headings and another for body text.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_customize_fonts.png\",\n                        alt: \"Customize fonts dialog box in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Select Design → Variants → Fonts → Customize Fonts, choose the heading and body fonts, then save the custom font theme.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing Theme Effects\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Theme effects control the appearance of shapes, SmartArt graphics, and other visual objects in your presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Changing theme effects can adjust elements such as shadows, glows, reflections, and shape styles.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_theme_effects.jpeg\",\n                        alt: \"Theme effects options in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To apply a different effect style, open the Design tab, click Variants, select Effects, and choose the desired effect.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing Background Styles\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also change the background style of your slides to further customize the appearance of your presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Background styles depend on the current theme and color settings.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_background_styles.png\",\n                        alt: \"Background styles options in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Open Design → Variants → Background Styles and choose a new background. For additional options, select Format Background.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Saving a Custom Theme\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After customizing colors, fonts, and effects, you can save your theme and reuse it in future presentations.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_save_current_theme.jpeg\",\n                        alt: \"Save current theme option in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Open the Themes gallery on the Design tab and select Save Current Theme.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_save_dialog.png\",\n                        alt: \"Save theme dialog box\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Enter a name for the theme and click Save. The theme will appear in the Custom section of the theme gallery.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Presentation Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After modifying theme colors, fonts, effects, and background styles, your presentation will have a customized and consistent design.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png\",\n                        alt: \"Final presentation after modifying theme\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Change the theme colors.\",\n                    \"Customize the fonts so the heading font is Garamond and the body font is Arial.\",\n                    \"Change the background style.\",\n                    \"Optional: Save your customized theme.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png\",\n                alt: \"Final result after modifying a theme\"\n            }\n        ]\n    },\n    {\n        slug: \"slide-master-view\",\n        title: \"Slide Master View\",\n        description: \"Learn how to use Slide Master view to make global design changes, create custom layouts, manage placeholders, and keep an entire presentation consistent.\",\n        duration: \"16 min\",\n        videoUrl: \"https://www.youtube.com/embed/h6ARCTypPTg\",\n        practiceFiles: [\n            {\n                name: \"Slide Master View Practice File\",\n                url: \"/practice/powerpoint/module-3/slide-master-view/Powerpoint_SlideMaster_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"What Slide Master View Does\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Slide Master view allows you to control the overall design and layout structure of an entire presentation. Instead of editing slides one by one, you can update the master and its layouts so that design changes appear everywhere they are used.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This is especially useful when you want consistent branding, repeated logos, matching fonts, and reusable slide layouts throughout a presentation.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Opening Slide Master View\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"To begin working with slide masters, go to the View tab and select Slide Master. PowerPoint will switch from the normal editing view into the master editing workspace.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon_view.png\",\n                        alt: \"View tab with Slide Master command in PowerPoint\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Once Slide Master view opens, the left pane will display the large master slide at the top and the related layouts below it.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master_select.png\",\n                        alt: \"Slide Master selected in the left pane\"\n                    }\n                ]\n            },\n            {\n                heading: \"Understanding the Master Slide and Layouts\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The top slide in Slide Master view is the master slide. It controls global elements such as theme fonts, background styling, and repeated objects like logos.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The smaller slides beneath it are layouts. Each layout controls the structure of a specific slide type such as title slides, content slides, or image-based slides.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master.png\",\n                        alt: \"Slide Master view showing hierarchy\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"When you apply a layout to a slide, that slide inherits all formatting and structure from that layout.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Editing Master Text and Branding\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can format text on the master or layouts just like regular slides, including font style, size, and alignment.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_text_formatting.png\",\n                        alt: \"Formatting text in Slide Master\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also insert logos or branding elements so they automatically appear on multiple slides.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_resize_move_logo.png\",\n                        alt: \"Logo placement\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Theme Fonts in Slide Master\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Slide Master view works closely with themes. Changing theme fonts will update text across all layouts instantly.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_theme_font.png\",\n                        alt: \"Theme fonts\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This ensures consistency and helps maintain a professional appearance.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Inserting and Managing Placeholders\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Placeholders define where content such as text, images, charts, and media will appear on a slide.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Use Insert Placeholder from the Slide Master tab to add placeholders to layouts.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_placeholders.png\",\n                        alt: \"Insert placeholder menu\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Once placed, you can resize and position placeholders to create structured layouts.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Creating a Custom Layout\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can create your own layouts to standardize how slides are structured across a presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon.png\",\n                        alt: \"Slide Master ribbon\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Custom layouts are useful for things like product slides, team slides, or image-focused content.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_select_layout.png\",\n                        alt: \"Selecting layout\"\n                    }\n                ]\n            },\n            {\n                heading: \"Renaming Layouts\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Renaming layouts makes them easier to identify and reuse later.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click Rename and assign a meaningful name such as Product Slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_layout.png\",\n                        alt: \"Rename layout\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_dialog.png\",\n                        alt: \"Rename dialog\"\n                    }\n                ]\n            },\n            {\n                heading: \"Showing and Hiding Master Elements\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can control whether titles, footers, and background elements appear on specific layouts.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_titles_footers.png\",\n                        alt: \"Footer options\"\n                    }\n                ]\n            },\n            {\n                heading: \"Applying Custom Layouts to Slides\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Apply layouts from the Home tab to instantly update slide structure and formatting.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_use_custom_layout.png\",\n                        alt: \"Applying layout\"\n                    }\n                ]\n            },\n            {\n                heading: \"Saving the Theme\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Save your customized theme to reuse it in future presentations.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_current_theme.png\",\n                        alt: \"Save theme\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_theme.png\",\n                        alt: \"Save dialog\"\n                    }\n                ]\n            },\n            {\n                heading: \"Closing Slide Master View\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Click Close Master View to return to the normal editing environment.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Presentation Example\",\n                blocks: [\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg\",\n                        alt: \"Final slides\"\n                    }\n                ]\n            },\n            // ✅ PRO TIP\n            {\n                heading: \"Pro Tip\",\n                blocks: [\n                    {\n                        type: \"callout\",\n                        variant: \"success\",\n                        text: \"If you find yourself repeating the same formatting changes across multiple slides, switch to Slide Master view. One change there updates every slide automatically.\"\n                    }\n                ]\n            },\n            // ✅ KNOWLEDGE CHECK\n            {\n                heading: \"Knowledge Check\",\n                blocks: [\n                    {\n                        type: \"knowledge-check\",\n                        question: \"What does Slide Master control?\",\n                        options: [\n                            \"Only one slide\",\n                            \"The entire presentation design\",\n                            \"Animations only\"\n                        ],\n                        correctIndex: 1\n                    },\n                    {\n                        type: \"knowledge-check\",\n                        question: \"What is a layout?\",\n                        options: [\n                            \"A color theme\",\n                            \"A slide structure template\",\n                            \"A font style\"\n                        ],\n                        correctIndex: 1\n                    },\n                    {\n                        type: \"knowledge-check\",\n                        question: \"Why are placeholders important?\",\n                        options: [\n                            \"To lock slides\",\n                            \"To define content areas\",\n                            \"To animate slides\"\n                        ],\n                        correctIndex: 1\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open the practice presentation.\",\n                    \"Go to the View tab and open Slide Master view.\",\n                    \"Select one of the layouts and rename it Product Slide.\",\n                    \"Insert a Picture placeholder on a custom layout.\",\n                    \"Move and resize the logo so it is aligned consistently on the layout.\",\n                    \"Change the theme font used for the layout.\",\n                    \"Return to Normal view.\",\n                    \"Apply the custom Product Slide layout to an existing slide.\",\n                    \"Save the current theme for future use.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg\",\n                alt: \"Final result\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/content/ms-office/powerpoint/module3Lessons.ts\n");

